import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

logger = logging.getLogger(__name__)

# addr_ : input = beta * input + alpha * outer(vec1, vec2)   (in-place)
#
# History / why this file no longer uses the original 32x32 2D-tile kernel:
#
# The previous revision tiled the output as a 2D [32, 32] block. On this XPU
# backend that kernel does not compile at all: the `TritonXPULegalize` pass
# aborts ("Failures have been detected while processing an MLIR pass
# pipeline"), so every dtype/shape failed. The sibling functional `addr.py`
# shows the access pattern the backend lowers well: one flat 1D tile over
# `M*N` elements, the column index declared as a `tl.constexpr`, and the row
# index derived as `tid // N`. That folds to a contiguous (stride-1) run for
# a contiguous input -> block DMA instead of a discrete 2D gather.
#
# This revision reuses that flat-tile design while keeping the in-place
# semantics: the same pointer is loaded from and stored to, so `input` is
# updated in place without a temporary output tensor or a second copy kernel.
#
# Tail handling: `num_tasks % TILE != 0` needs a partial tile. An earlier
# attempt clamped the tail task index to `num_tasks - 1` so the tail lanes
# would rewrite the last element with its own value; that is NOT idempotent
# for an in-place non-idempotent update, because the duplicated lanes can read
# the element after another lane has already stored the new value (the last
# element then converges to the update's fixed point). So the non-even path
# uses a real mask on both load and store, while the `num_tasks % TILE == 0`
# case (all benchmark shapes) compiles the mask away through the `EVEN`
# constexpr and keeps the unmasked block-DMA path.

_MAX_TILE = 2048


@triton.jit(do_not_specialize=["beta", "alpha"])
def addr_inplace_kernel(
    inp_ptr,
    v1_ptr,
    v2_ptr,
    beta,
    alpha,
    in_s0: tl.constexpr,
    in_s1: tl.constexpr,
    v1_s: tl.constexpr,
    v2_s: tl.constexpr,
    N: tl.constexpr,
    num_tasks: tl.constexpr,
    TILE: tl.constexpr,
    EVEN: tl.constexpr,
):
    tid = tl.program_id(0) * TILE + tl.arange(0, TILE)
    if EVEN:
        mask = None
    else:
        mask = tid < num_tasks

    i1 = tid % N
    i0 = tid // N
    off = i0 * in_s0 + i1 * in_s1

    if EVEN:
        x = tl.load(inp_ptr + off).to(tl.float32)
        s = tl.load(v1_ptr + i0 * v1_s).to(tl.float32)
        w = tl.load(v2_ptr + i1 * v2_s).to(tl.float32)
    else:
        x = tl.load(inp_ptr + off, mask=mask, other=0.0).to(tl.float32)
        s = tl.load(v1_ptr + i0 * v1_s, mask=mask, other=0.0).to(tl.float32)
        w = tl.load(v2_ptr + i1 * v2_s, mask=mask, other=0.0).to(tl.float32)

    # fp32 accumulation, stored back in the input dtype.
    y = beta * x + alpha * (s * w)
    if EVEN:
        tl.store(inp_ptr + off, y.to(inp_ptr.dtype.element_ty))
    else:
        tl.store(inp_ptr + off, y.to(inp_ptr.dtype.element_ty), mask=mask)


def addr_(input, vec1, vec2, *, beta=1, alpha=1):
    logger.debug("GEMS_KUNLUNXIN ADDR_")
    if vec1.dim() != 1 or vec2.dim() != 1:
        raise ValueError("addr_: expected 1-D vectors")

    # ATen types alpha/beta as Scalar: a 0-dim tensor argument must behave as
    # a python number (and a 0-dim tensor cannot be passed as a kernel scalar).
    if torch.is_tensor(beta) and beta.numel() == 1:
        beta = beta.item()
    if torch.is_tensor(alpha) and alpha.numel() == 1:
        alpha = alpha.item()

    if input.dim() != 2:
        raise ValueError(f"addr_: expected 2-D input, got shape {input.shape}")

    M, N = input.shape
    if vec1.shape[0] != M or vec2.shape[0] != N:
        raise ValueError(
            f"addr_: vec1 size {vec1.shape[0]} must match input rows {M}, "
            f"vec2 size {vec2.shape[0]} must match input cols {N}"
        )

    num_tasks = M * N
    # Zero-sized tensor: nothing to compute, keep the in-place contract.
    if num_tasks == 0:
        return input

    tile = min(_MAX_TILE, triton.next_power_of_2(num_tasks))
    grid = (triton.cdiv(num_tasks, tile),)
    num_warps = 4 if tile <= 2048 else 8

    with torch_device_fn.device(input.device):
        addr_inplace_kernel[grid](
            input,
            vec1,
            vec2,
            beta,
            alpha,
            input.stride(0),
            input.stride(1),
            vec1.stride(0),
            vec2.stride(0),
            N,
            num_tasks,
            TILE=tile,
            EVEN=(num_tasks % tile == 0),
            num_warps=num_warps,
        )
    return input
